"""Maintain the reference-inspired XML UI. No layout is constructed at runtime."""
from pathlib import Path
from xml.dom import minidom
import xml.etree.ElementTree as ET

RES = Path(__file__).resolve().parents[1] / 'app/src/main/res'
A = 'http://schemas.android.com/apk/res/android'
P = 'http://schemas.android.com/apk/res-auto'
ET.register_namespace('android', A)
ET.register_namespace('app', P)
def put(relative, source):
    path = RES / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    doc = minidom.parseString(source)
    def strip_whitespace(node):
        for child in list(node.childNodes):
            if child.nodeType == child.TEXT_NODE and not child.data.strip():
                node.removeChild(child)
            else: strip_whitespace(child)
    strip_whitespace(doc)
    path.write_text(doc.toprettyxml(indent='    '), encoding='utf-8')

def label(value, size=16, color='@color/text_primary', extra=''):
    return f'<TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:text="{value}" android:textSize="{size}sp" android:textColor="{color}" android:fontFamily="sans-serif" {extra}/>'

def action(id, title, style='PrimaryButton', extra=''):
    return f'<com.google.android.material.button.MaterialButton android:id="@+id/{id}" style="@style/{style}" android:layout_width="match_parent" android:layout_height="52dp" android:text="{title}" android:letterSpacing="0" android:textSize="16sp" {extra}/>'

def field(id, hint, icon, kind='text', extra=''):
    return f'''<com.google.android.material.textfield.TextInputLayout style="@style/CustomEditText" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginBottom="16dp" app:hintEnabled="false" app:startIconDrawable="@drawable/{icon}" app:startIconTint="@color/text_secondary" app:endIconMode="{'password_toggle' if kind=='textPassword' else 'none'}" app:endIconTint="@color/text_secondary">
    <com.google.android.material.textfield.TextInputEditText android:id="@+id/{id}" android:layout_width="match_parent" android:layout_height="56dp" android:hint="{hint}" android:textColor="@color/text_primary" android:textColorHint="@color/text_secondary" android:textSize="15sp" android:fontFamily="sans-serif" android:paddingVertical="12dp" android:singleLine="true" android:inputType="{kind}" {extra}/></com.google.android.material.textfield.TextInputLayout>'''

def root(content, background='@drawable/bg_auth_surface'):
    return f'<FrameLayout xmlns:android="{A}" xmlns:app="{P}" android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:background="{background}">{content}</FrameLayout>'

def toolbar(title='', hidden=False):
    return f'<com.google.android.material.appbar.MaterialToolbar android:id="@+id/toolbar" android:layout_width="match_parent" android:layout_height="56dp" app:title="{title}" app:titleTextAppearance="@style/GalleryToolbarTitle" app:titleTextColor="@color/text_primary" app:navigationIcon="@drawable/ic_arrow_back" app:navigationIconTint="@color/text_primary"'+(' android:visibility="gone"' if hidden else '')+'/>'

def polish():
    colors = ET.parse(RES/'values/colors.xml').getroot()
    for child in colors:
        if child.tail: child.tail = None
    if colors.text: colors.text = None
    updates={'primary':'#2864FF','primary_dark':'#1951E8','primary_light':'#DCE9FF',
             'text_primary':'#102C63','text_secondary':'#526D99','text_hint':'#7084A6',
             'background':'#F6F9FF','surface':'#FFFFFF','field_border':'#CEDDF3'}
    existing={c.attrib.get('name'):c for c in colors}
    for name,value in updates.items():
        child=existing.get(name)
        if child is None:child=ET.SubElement(colors,'color',{'name':name})
        child.text=value
    put('values/colors.xml',ET.tostring(colors,encoding='unicode'))
    put('values-night/colors.xml','''<resources><color name="background">#10151F</color><color name="surface">#1C2534</color><color name="text_primary">#EDF3FF</color><color name="text_secondary">#ABBBD5</color><color name="text_hint">#8F9FB8</color><color name="field_border">#35435A</color><color name="primary_light">#253A61</color></resources>''')
    put('drawable/bg_auth_surface.xml','''<shape xmlns:android="http://schemas.android.com/apk/res/android"><gradient android:angle="315" android:startColor="#FFFFFF" android:centerColor="#F3F7FF" android:endColor="#EFF5FF"/></shape>''')
    put('drawable-night/bg_auth_surface.xml','''<shape xmlns:android="http://schemas.android.com/apk/res/android"><solid android:color="#10151F"/></shape>''')
    put('drawable/bg_logo_tile.xml','''<shape xmlns:android="http://schemas.android.com/apk/res/android"><solid android:color="#FFFFFF"/><corners android:radius="24dp"/><stroke android:width="1dp" android:color="#E7EEFC"/></shape>''')
    # Eight translucent petals, aligned like the reference flower, rather than a four-color cross.
    petals=''.join(f'<group android:pivotX="48" android:pivotY="48" android:rotation="{i*45}"><path android:fillColor="{c}" android:fillAlpha="0.93" android:pathData="M48,49C34,40 32,27 38,20C43,13 53,13 58,20C65,30 60,41 48,49Z"/></group>' for i,c in enumerate(['#FF5A31','#FFBD25','#7DCD39','#28C68B','#25BDE5','#2784F4','#7057F6','#D646ED']))
    put('drawable/ic_app_logo.xml',f'<vector xmlns:android="{A}" android:width="96dp" android:height="96dp" android:viewportWidth="96" android:viewportHeight="96">{petals}<path android:fillColor="#FFFFFF" android:pathData="M48,43a5,5 0,1 0,0 10a5,5 0,1 0,0 -10"/></vector>')
    put('drawable/ic_launcher_foreground.xml',f'<inset xmlns:android="{A}" android:drawable="@drawable/ic_app_logo" android:inset="18dp"/>')
    put('drawable/ic_launcher_background.xml',f'<shape xmlns:android="{A}"><solid android:color="#F3F7FF"/></shape>')
    for name in ['ic_launcher','ic_launcher_round']:
        put(f'mipmap-anydpi-v26/{name}.xml',f'<adaptive-icon xmlns:android="{A}"><background android:drawable="@drawable/ic_launcher_background"/><foreground android:drawable="@drawable/ic_launcher_foreground"/></adaptive-icon>')
    # Layered landscape and floating photo prints are a vector asset, keeping the welcome screen light.
    photos=''
    for x,y,r in [(88,92,-17),(183,69,12),(139,137,-5)]:
        photos+=f'''<group android:translateX="{x}" android:translateY="{y}" android:rotation="{r}" android:pivotX="36" android:pivotY="36"><path android:fillColor="#D3E3F7" android:pathData="M2,3h77v83h-77Z"/><path android:fillColor="#FFFFFF" android:pathData="M0,0h76v82h-76Z"/><path android:fillColor="#B9E2FF" android:pathData="M6,6h64v60h-64Z"/><path android:fillColor="#FFD168" android:pathData="M55,12a8,8 0,1 0,0 16a8,8 0,1 0,0 -16"/><path android:fillColor="#53AD98" android:pathData="M6,56L28,26L47,48L58,35L70,54V66H6Z"/><path android:fillColor="#8ED58A" android:pathData="M6,61L23,48L43,60L59,50L70,60V66H6Z"/></group>'''
    put('drawable/art_splash.xml',f'''<vector xmlns:android="{A}" android:width="360dp" android:height="410dp" android:viewportWidth="360" android:viewportHeight="410">
    <path android:fillColor="#E6F0FF" android:pathData="M0,126Q30,110 55,138Q99,166 120,139Q160,104 199,142Q236,165 269,130Q312,95 360,127V410H0Z"/>
    <path android:fillColor="#C1D9FF" android:pathData="M0,211Q20,167 45,180L80,217L124,161L172,210L218,171L262,218L304,167L360,211V410H0Z"/>
    <path android:fillColor="#96BEF8" android:pathData="M0,274L40,225L79,253L130,205L188,274L238,218L286,262L330,222L360,243V410H0Z"/>
    <path android:fillColor="#72A9EA" android:pathData="M0,319Q45,261 92,294Q143,324 184,283Q244,255 287,296Q330,266 360,297V410H0Z"/>
    <path android:fillColor="#B8DCF7" android:pathData="M106,410Q165,359 161,328Q156,300 204,289Q172,321 199,348Q225,379 258,410Z"/>
    <path android:fillColor="#A0D6B0" android:pathData="M0,355Q22,324 56,348Q81,326 110,350L76,410H0Z M272,410L268,362Q300,328 324,351Q344,328 360,349V410Z"/>
    <path android:fillColor="#6BBF9E" android:pathData="M0,390Q25,356 56,372Q69,345 92,373Q103,367 117,389L124,410H0Z M242,410Q264,369 291,383Q299,361 321,375Q345,358 360,381V410Z"/>
    <path android:fillColor="#D4E6FF" android:pathData="M28,57Q25,46 36,42Q49,37 54,50Q67,47 69,59Q69,65 60,65H31Q24,64 28,57Z M286,84Q280,74 290,69Q303,62 310,76Q322,72 325,84Q324,91 316,91H290Z"/>
    <path android:fillColor="#71B5FC" android:pathData="M61,92l5,-4l4,5l-5,4Z M281,139l4,-3l3,5l-4,2Z M109,64l3,-3l3,3l-3,3Z"/>
    <path android:fillColor="#FFC754" android:pathData="M165,48l5,2l-2,7l-4,-2Z M264,118l6,1l-1,5l-6,-1Z"/>
    {photos}</vector>''')
    splash=toolbar(hidden=True)+f'''<androidx.constraintlayout.widget.ConstraintLayout android:layout_width="match_parent" android:layout_height="match_parent">
    <androidx.constraintlayout.widget.Guideline android:id="@+id/heroAnchor" android:layout_width="wrap_content" android:layout_height="wrap_content" android:orientation="horizontal" app:layout_constraintGuide_percent="0.14"/>
    <ImageView android:id="@+id/welcomeLogo" android:layout_width="80dp" android:layout_height="80dp" android:padding="10dp" android:background="@drawable/bg_logo_tile" android:elevation="3dp" android:src="@drawable/ic_app_logo" android:contentDescription="Ảnh" app:layout_constraintTop_toBottomOf="@id/heroAnchor" app:layout_constraintStart_toStartOf="parent" app:layout_constraintEnd_toEndOf="parent"/>
    <TextView android:id="@+id/welcomeTitle" android:layout_width="wrap_content" android:layout_height="wrap_content" android:text="Ảnh" android:textSize="46sp" android:textColor="@color/text_primary" android:fontFamily="sans-serif-medium" android:layout_marginTop="12dp" app:layout_constraintTop_toBottomOf="@id/welcomeLogo" app:layout_constraintStart_toStartOf="parent" app:layout_constraintEnd_toEndOf="parent"/>
    <TextView android:id="@+id/welcomeSubtitle" android:layout_width="wrap_content" android:layout_height="wrap_content" android:text="Lưu giữ khoảnh khắc đẹp" android:textColor="@color/text_secondary" android:textSize="16sp" android:layout_marginTop="4dp" app:layout_constraintTop_toBottomOf="@id/welcomeTitle" app:layout_constraintStart_toStartOf="parent" app:layout_constraintEnd_toEndOf="parent"/>
    <ImageView android:id="@+id/welcomeArt" android:layout_width="0dp" android:layout_height="0dp" android:src="@drawable/art_splash" android:scaleType="fitXY" android:contentDescription="Những tấm ảnh giữa phong cảnh núi xanh" app:layout_constraintStart_toStartOf="parent" app:layout_constraintEnd_toEndOf="parent" app:layout_constraintBottom_toBottomOf="parent" app:layout_constraintTop_toBottomOf="@id/welcomeSubtitle"/>
    <com.google.android.material.button.MaterialButton android:id="@+id/start" style="@style/PrimaryButton" android:layout_width="0dp" android:layout_height="52dp" android:layout_marginHorizontal="60dp" android:text="Bắt đầu" android:textSize="16sp" android:layout_marginBottom="8dp" app:layout_constraintBottom_toTopOf="@id/guest" app:layout_constraintStart_toStartOf="parent" app:layout_constraintEnd_toEndOf="parent"/>
    <com.google.android.material.button.MaterialButton android:id="@+id/guest" style="@style/TextButton" android:layout_width="wrap_content" android:layout_height="48dp" android:text="Khám phá trên thiết bị" android:textSize="14sp" android:backgroundTint="#E8F2FF" android:layout_marginBottom="36dp" app:cornerRadius="14dp" app:layout_constraintBottom_toBottomOf="parent" app:layout_constraintStart_toStartOf="parent" app:layout_constraintEnd_toEndOf="parent"/>
    </androidx.constraintlayout.widget.ConstraintLayout>'''
    put('layout/activity_splash.xml',root(splash))
    for register in [False,True]:
        title='Đăng ký' if register else 'Đăng nhập'
        subtitle='Tạo tài khoản để bắt đầu' if register else 'Chào mừng bạn quay lại!'
        content=f'<TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:text="{title}" android:textSize="30sp" android:fontFamily="sans-serif-medium" android:textColor="@color/text_primary"/>'
        content+=label(subtitle,16,'@color/text_secondary','android:layout_marginTop="8dp" android:layout_marginBottom="36dp"')
        if register:content+=field('name','Họ và tên','ic_person','textPersonName','android:imeOptions="actionNext"')
        content+=field('email','Email hoặc số điện thoại','ic_email','textEmailAddress','android:imeOptions="actionNext"')+field('password','Mật khẩu','ic_lock','textPassword','android:imeOptions="actionDone"')
        content+=action('submit',title,extra='android:layout_marginTop="8dp"')
        content+=action('forgot','Quên mật khẩu?','TextButton',extra='android:layout_marginTop="4dp"'+(' android:visibility="gone"' if register else ''))
        content+=f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center" android:orientation="horizontal" android:layout_marginTop="{32 if register else 24}dp" android:layout_marginBottom="20dp"><View android:layout_width="0dp" android:layout_height="1dp" android:layout_weight="1" android:background="@color/field_border"/><TextView android:layout_width="wrap_content" android:layout_height="wrap_content" android:paddingHorizontal="16dp" android:text="Hoặc đăng nhập bằng" android:textSize="13sp" android:textColor="@color/text_secondary"/><View android:layout_width="0dp" android:layout_height="1dp" android:layout_weight="1" android:background="@color/field_border"/></LinearLayout>'
        content+=action('google','Tiếp tục với Google','OutlinedButton','app:icon="@drawable/ic_google" app:iconTint="@null" app:iconGravity="textStart" app:iconPadding="16dp"')
        content+='<ProgressBar android:id="@+id/authProgress" style="?android:attr/progressBarStyleHorizontal" android:layout_width="match_parent" android:layout_height="4dp" android:layout_marginTop="16dp" android:indeterminate="true" android:visibility="gone"/>'
        content+=label('',14,'@color/text_secondary','android:id="@+id/status" android:layout_marginTop="12dp" android:visibility="gone" android:accessibilityLiveRegion="polite"')
        content+='<Space android:layout_width="1dp" android:layout_height="0dp" android:layout_weight="1" android:minHeight="52dp"/>'
        content+=action('switchAuth','Đã có tài khoản? Đăng nhập' if register else 'Chưa có tài khoản? Đăng ký','TextButton','android:layout_marginTop="32dp"')
        scroll=f'<androidx.core.widget.NestedScrollView android:layout_width="match_parent" android:layout_height="match_parent" android:fillViewport="true" android:clipToPadding="false"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:paddingHorizontal="28dp" android:paddingTop="64dp" android:paddingBottom="20dp">{content}</LinearLayout></androidx.core.widget.NestedScrollView>'
        put('layout/activity_register.xml' if register else 'layout/activity_login.xml',root(toolbar(hidden=True)+scroll))
    # Apply readable typography, colors and compact controls to every remaining screen.
    for path in (RES/'layout').glob('*.xml'):
        if path.stem in ['activity_splash','activity_login','activity_register']:continue
        tree=ET.parse(path);r=tree.getroot()
        if r.attrib.get(f'{{{A}}}id')=='@+id/screenRoot':r.set(f'{{{A}}}background','@color/background')
        for node in r.iter():
            tag=node.tag.rsplit('.',1)[-1]
            if tag=='MaterialToolbar':
                node.set(f'{{{A}}}layout_height','56dp');node.set(f'{{{P}}}titleTextAppearance','@style/GalleryToolbarTitle');node.set(f'{{{P}}}navigationIconTint','@color/text_primary')
            if tag=='TextView':
                node.set(f'{{{A}}}fontFamily','sans-serif')
                size=node.attrib.get(f'{{{A}}}textSize','14sp')
                if size in ['11sp','12sp','13sp']:node.set(f'{{{A}}}textSize','14sp')
                if node.attrib.get(f'{{{A}}}id')=='@+id/status':
                    node.set(f'{{{A}}}text','');node.set(f'{{{A}}}visibility','gone')
            if tag=='MaterialButton':node.set(f'{{{A}}}letterSpacing','0')
            if tag=='BottomNavigationView':
                node.set(f'{{{A}}}layout_height','68dp');node.set(f'{{{A}}}background','@color/surface');node.set(f'{{{P}}}itemIconTint','@color/nav_colors');node.set(f'{{{P}}}itemTextColor','@color/nav_colors');node.attrib.pop(f'{{{P}}}itemActiveIndicatorEnabled',None);node.set(f'{{{P}}}itemTextAppearanceActive','@style/GalleryNavigationText');node.set(f'{{{P}}}itemTextAppearanceInactive','@style/GalleryNavigationText')
            if tag=='Chip':
                node.set(f'{{{P}}}chipBackgroundColor','@color/chip_background');node.set(f'{{{A}}}textColor','@color/chip_text');node.set(f'{{{P}}}chipStrokeColor','@color/field_border');node.set(f'{{{P}}}chipStrokeWidth','1dp');node.set(f'{{{P}}}checkedIconVisible','false');node.set(f'{{{A}}}textSize','14sp');node.set(f'{{{P}}}chipMinHeight','36dp')
        put('layout/'+path.name,ET.tostring(r,encoding='unicode').replace('\n',''))
    polish_gallery_and_panels()
    polish_secondary_screens()
    from album_screens import polish_albums
    polish_albums()
    from editor_screens import polish_editor
    polish_editor()
    from theme_resources import apply_theme_resources
    apply_theme_resources()
    print('Applied reference-inspired layouts and assets.')

def navigation():
    return '<com.google.android.material.bottomnavigation.BottomNavigationView android:id="@+id/navigation" android:layout_width="match_parent" android:layout_height="68dp" android:background="@color/surface" app:menu="@menu/bottom_navigation_menu" app:labelVisibilityMode="labeled" app:itemIconTint="@color/nav_colors" app:itemTextColor="@color/nav_colors" app:itemTextAppearanceActive="@style/GalleryNavigationText" app:itemTextAppearanceInactive="@style/GalleryNavigationText"/>'

def row(id,title,icon,red=False):
    return f'<com.google.android.material.button.MaterialButton android:id="@+id/{id}" style="@style/GalleryRow" android:layout_width="match_parent" android:layout_height="56dp" android:text="{title}" app:icon="@drawable/{icon}"'+(' android:textColor="#DB3546" app:iconTint="#DB3546"' if red else '')+'/>'

def polish_gallery_and_panels():
    xmlns=f'xmlns:android="{A}" xmlns:app="{P}"'
    put('drawable/bg_search_bar.xml',f'<shape xmlns:android="{A}"><solid android:color="@color/primary_light"/><corners android:radius="24dp"/><stroke android:width="1dp" android:color="@color/field_border"/></shape>')
    status=label('',14,'@color/text_secondary','android:id="@+id/status" android:visibility="gone" android:paddingVertical="8dp"')
    for name,title in [('activity_main','Ảnh'),('activity_search','Tìm kiếm'),('activity_dark_gallery','Ảnh')]:
        # A dedicated search field avoids inherited TextInputLayout vertical
        # padding clipping Vietnamese accents in a compact 48dp search bar.
        search='''<FrameLayout android:layout_width="match_parent" android:layout_height="48dp" android:background="@drawable/bg_search_bar">
        <ImageView android:layout_width="20dp" android:layout_height="20dp" android:layout_gravity="start|center_vertical" android:layout_marginStart="14dp" android:src="@drawable/ic_search" app:tint="@color/text_secondary" android:importantForAccessibility="no"/>
        <androidx.appcompat.widget.AppCompatEditText android:id="@+id/search" android:layout_width="match_parent" android:layout_height="match_parent" android:background="@android:color/transparent" android:paddingStart="44dp" android:paddingEnd="12dp" android:paddingTop="0dp" android:paddingBottom="0dp" android:gravity="center_vertical" android:includeFontPadding="true" android:fontFamily="sans-serif" android:singleLine="true" android:hint="Tìm kiếm ảnh, video…" android:textSize="15sp" android:inputType="text" android:imeOptions="actionSearch" android:textColor="@color/text_primary" android:textColorHint="@color/text_secondary"/>
        </FrameLayout>'''
        chips='<com.google.android.material.chip.ChipGroup android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="6dp" app:singleLine="false" app:singleSelection="true" app:selectionRequired="true" app:chipSpacingHorizontal="6dp">'+''.join(f'<com.google.android.material.chip.Chip android:id="@+id/{id}" android:layout_width="wrap_content" android:layout_height="48dp" android:text="{value}" android:textSize="14sp" android:textColor="@color/chip_text" android:checkable="true" android:checked="{str(i==0).lower()}" app:chipBackgroundColor="@color/chip_background" app:chipStrokeColor="@color/field_border" app:chipStrokeWidth="1dp" app:checkedIconVisible="false" app:chipCornerRadius="18dp" app:ensureMinTouchTargetSize="true"/>' for i,(id,value) in enumerate([('all','Tất cả'),('images','Ảnh'),('videos','Video'),('favorites','Yêu thích')]))+'</com.google.android.material.chip.ChipGroup>'
        sort=action('sort','Sắp xếp và bộ lọc','TextButton','app:icon="@drawable/ic_filter" app:iconGravity="textStart"') if name=='activity_search' else ''
        empty='<LinearLayout android:id="@+id/emptyState" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:gravity="center" android:visibility="gone" android:padding="28dp"><ImageView android:layout_width="180dp" android:layout_height="150dp" android:src="@drawable/art_splash" android:contentDescription="Thư viện của bạn"/>'+label('Lưu giữ những điều bạn yêu',20,extra='android:gravity="center" android:layout_marginTop="16dp"')+label('Thêm ảnh hoặc video đầu tiên\nđể bắt đầu câu chuyện của bạn.',15,'@color/text_secondary','android:gravity="center" android:layout_marginTop="10dp" android:lineSpacingExtra="4dp"')+'</LinearLayout>'
        grid=f'<FrameLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1"><androidx.recyclerview.widget.RecyclerView android:id="@+id/grid" android:layout_width="match_parent" android:layout_height="match_parent" android:paddingBottom="84dp" android:clipToPadding="false"/>{empty}<com.google.android.material.floatingactionbutton.FloatingActionButton android:id="@+id/importMedia" android:layout_width="wrap_content" android:layout_height="wrap_content" android:layout_gravity="bottom|end" android:layout_margin="16dp" android:src="@drawable/ic_add" android:contentDescription="Thêm ảnh hoặc video" app:backgroundTint="@color/primary" app:tint="#FFFFFF" app:fabCustomSize="56dp"/></FrameLayout>'
        put(f'layout/{name}.xml',f'<LinearLayout {xmlns} android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="@color/background">{toolbar(title)}<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:orientation="vertical" android:paddingHorizontal="16dp">{search}{chips}{sort}{status}{grid}</LinearLayout>{navigation()}</LinearLayout>')
    panels=[('sheet_filter','Bộ lọc',[('newest','Mới nhất','ic_calendar'),('oldest','Cũ nhất','ic_sort'),('size','Kích thước','ic_image_size'),('type','Tên A → Z','ic_file_type')]),
      ('sheet_options','Tùy chọn',[('select','Chọn nhiều','ic_select_all'),('addAlbum','Thêm vào album','ic_album'),('hide','Ẩn các mục đã chọn','ic_visibility_off'),('hiddenMedia','Ảnh và video đã ẩn','ic_visibility_off'),('settings','Cài đặt','ic_settings'),('help','Trợ giúp','ic_help')]),
      ('sheet_photo_context','Ảnh của bạn',[('info','Xem chi tiết','ic_info'),('addAlbum','Thêm vào album','ic_album'),('favorite','Yêu thích','ic_favorite_outline'),('hide','Ẩn / Bỏ ẩn','ic_visibility_off'),('edit','Chỉnh sửa','ic_edit'),('share','Chia sẻ','ic_share'),('trash','Chuyển vào thùng rác','ic_delete')]),
      ('sheet_share','Chia sẻ ảnh',[('shareFile','Chia sẻ qua ứng dụng','ic_share'),('shareLink','Chia sẻ liên kết sao lưu','ic_cloud_done'),('cancel','Hủy','ic_close')])]
    for name,title,rows in panels:
        put(f'layout/{name}.xml',f'<LinearLayout {xmlns} android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:background="@drawable/bg_bottom_sheet" android:padding="8dp"><View android:layout_width="36dp" android:layout_height="4dp" android:layout_gravity="center_horizontal" android:layout_marginTop="8dp" android:layout_marginBottom="8dp" android:background="@drawable/bg_handle_bar"/>{toolbar(title)}<androidx.core.widget.NestedScrollView android:layout_width="match_parent" android:layout_height="wrap_content"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:paddingBottom="12dp">'+''.join(row(*r,red=r[0]=='trash') for r in rows)+'</LinearLayout></androidx.core.widget.NestedScrollView></LinearLayout>')
    polish_settings()
    # A full image on a dark canvas with a compact horizontal action strip.
    actions=''.join(f'<com.google.android.material.button.MaterialButton android:id="@+id/{id}" style="@style/TextButton" android:layout_width="0dp" android:layout_weight="1" android:layout_height="76dp" android:text="{title}" android:textColor="#FFFFFF" android:textSize="12sp" android:letterSpacing="0" android:paddingHorizontal="0dp" app:icon="@drawable/{icon}" app:iconGravity="textTop" app:iconTint="#FFFFFF" app:iconSize="22dp" app:iconPadding="6dp"/>' for id,title,icon in [('favorite','Yêu thích','ic_favorite_outline'),('edit','Chỉnh sửa','ic_edit'),('share','Chia sẻ','ic_share')])
    actions+='<com.google.android.material.button.MaterialButton android:id="@+id/deletePhoto" style="@style/TextButton" android:layout_width="0dp" android:layout_weight="1" android:layout_height="76dp" android:text="Xóa" android:textColor="#FFFFFF" android:textSize="12sp" app:icon="@drawable/ic_delete" app:iconGravity="textTop" app:iconTint="#FFFFFF" app:iconSize="22dp"/>'
    put('layout/activity_photo_detail.xml',f'<LinearLayout {xmlns} android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="#080D17"><FrameLayout android:layout_width="match_parent" android:layout_height="56dp"><com.google.android.material.appbar.MaterialToolbar android:id="@+id/toolbar" android:layout_width="match_parent" android:layout_height="match_parent" app:navigationIcon="@drawable/ic_arrow_back" app:navigationIconTint="#FFFFFF"/><ImageButton android:id="@+id/more" android:layout_width="48dp" android:layout_height="48dp" android:layout_gravity="end|center_vertical" android:background="?attr/selectableItemBackgroundBorderless" android:src="@drawable/ic_more_vert" app:tint="#FFFFFF" android:contentDescription="Thông tin và thao tác"/></FrameLayout><ImageView android:id="@+id/photo" android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:scaleType="fitCenter" android:contentDescription="Ảnh đang xem"/>'+label('',13,'#C1CEE0','android:id="@+id/status" android:padding="12dp" android:visibility="gone"')+f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="horizontal" android:background="#121C2B">{actions}</LinearLayout></LinearLayout>')
    put('layout/item_media.xml',f'''<com.google.android.material.card.MaterialCardView {xmlns} android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_margin="2dp" app:cardCornerRadius="8dp" app:cardElevation="0dp" app:strokeWidth="0dp"><androidx.constraintlayout.widget.ConstraintLayout android:layout_width="match_parent" android:layout_height="wrap_content"><ImageView android:id="@+id/thumbnail" android:layout_width="0dp" android:layout_height="0dp" android:scaleType="centerCrop" android:contentDescription="Ảnh" app:layout_constraintDimensionRatio="1:1" app:layout_constraintTop_toTopOf="parent" app:layout_constraintStart_toStartOf="parent" app:layout_constraintEnd_toEndOf="parent"/><TextView android:id="@+id/caption" android:layout_width="wrap_content" android:layout_height="wrap_content" android:layout_margin="6dp" android:background="#66081224" android:padding="4dp" android:textColor="#FFFFFF" android:textSize="12sp" app:layout_constraintStart_toStartOf="parent" app:layout_constraintBottom_toBottomOf="@id/thumbnail"/><TextView android:id="@+id/check" android:layout_width="28dp" android:layout_height="28dp" android:layout_margin="6dp" android:visibility="gone" android:contentDescription="Đã chọn" app:layout_constraintTop_toTopOf="parent" app:layout_constraintEnd_toEndOf="parent" android:background="@drawable/bg_selection_number" android:textColor="@color/white" android:textSize="14sp" android:fontFamily="sans-serif-medium" android:gravity="center" android:includeFontPadding="false" android:elevation="2dp"/></androidx.constraintlayout.widget.ConstraintLayout></com.google.android.material.card.MaterialCardView>''')
    put('layout/item_album.xml',f'''<com.google.android.material.card.MaterialCardView {xmlns} android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_margin="6dp" app:cardCornerRadius="14dp" app:cardElevation="0dp" app:cardBackgroundColor="@color/surface" app:strokeWidth="0dp"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical"><ImageView android:id="@+id/thumbnail" android:layout_width="match_parent" android:layout_height="140dp" android:scaleType="centerCrop" android:contentDescription="Ảnh bìa album"/><TextView android:id="@+id/caption" android:layout_width="match_parent" android:layout_height="wrap_content" android:minHeight="62dp" android:padding="12dp" android:textColor="@color/text_primary" android:textSize="15sp" android:fontFamily="sans-serif-medium" android:lineSpacingExtra="4dp"/><ImageView android:id="@+id/check" android:layout_width="1dp" android:layout_height="1dp" android:visibility="gone" android:contentDescription="Đã chọn"/></LinearLayout></com.google.android.material.card.MaterialCardView>''')
    boxes=''.join(f'<EditText android:id="@+id/otp{i}" android:layout_width="0dp" android:layout_weight="1" android:layout_height="58dp" android:layout_marginHorizontal="3dp" android:background="@drawable/bg_otp_box" android:textColor="@color/text_primary" android:textSize="22sp" android:fontFamily="sans-serif-medium" android:gravity="center" android:inputType="number" android:selectAllOnFocus="true" android:maxLength="6" android:importantForAutofill="no" android:contentDescription="Chữ số {i}"/>' for i in range(1,7))
    otp=label('Xác thực tài khoản',25,extra='android:layout_marginTop="24dp"')+label('',16,'@color/text_secondary','android:id="@+id/status" android:layout_marginTop="12dp" android:lineSpacingExtra="5dp"')+f'<LinearLayout android:id="@+id/otpBoxes" android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="horizontal" android:layout_marginTop="36dp" android:layout_marginBottom="28dp">{boxes}</LinearLayout><EditText android:id="@+id/otp" android:layout_width="1dp" android:layout_height="1dp" android:visibility="gone" android:inputType="number"/>'+action('verify','Xác thực')+action('resend','Gửi lại xác thực','TextButton','android:layout_marginTop="12dp"')
    put('layout/activity_otp.xml',f'<LinearLayout {xmlns} android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="@drawable/bg_auth_surface">{toolbar()}<androidx.core.widget.NestedScrollView android:layout_width="match_parent" android:layout_height="match_parent"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:paddingHorizontal="24dp">{otp}</LinearLayout></androidx.core.widget.NestedScrollView></LinearLayout>')
    tools=''.join(f'<com.google.android.material.button.MaterialButton android:id="@+id/{id}" style="@style/TextButton" android:layout_width="0dp" android:layout_weight="1" android:layout_height="76dp" android:text="{title}" android:textColor="#FFFFFF" android:textSize="12sp" android:letterSpacing="0" android:paddingHorizontal="0dp" app:icon="@drawable/{icon}" app:iconGravity="textTop" app:iconSize="22dp" app:iconTint="#FFFFFF"/>' for id,title,icon in [('crop','Cắt 1:1','ic_crop'),('rotate','Xoay','ic_rotate'),('filter','Bộ lọc','ic_filter'),('draw','Vẽ','ic_edit')])
    put('layout/activity_edit_photo.xml',f'<LinearLayout {xmlns} android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="#080D17"><com.google.android.material.appbar.MaterialToolbar android:id="@+id/toolbar" android:layout_width="match_parent" android:layout_height="56dp" app:title="Chỉnh sửa" app:titleTextColor="#FFFFFF" app:navigationIcon="@drawable/ic_arrow_back" app:navigationIconTint="#FFFFFF"/><ImageView android:id="@+id/photo" android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:layout_margin="16dp" android:scaleType="fitCenter" android:contentDescription="Ảnh chỉnh sửa"/><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="horizontal">{tools}</LinearLayout>'+label('Độ sáng',14,'#D9E5F9','android:paddingHorizontal="24dp"')+'<SeekBar android:id="@+id/brightness" android:layout_width="match_parent" android:layout_height="48dp" android:layout_marginHorizontal="16dp" android:max="200" android:progress="100"/>'+label('',14,'#D9E5F9','android:id="@+id/status" android:visibility="gone" android:paddingHorizontal="24dp"')+f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:padding="20dp">{action("save","Lưu bản sao")}</LinearLayout></LinearLayout>')
    backup=label('Giữ an toàn mọi khoảnh khắc',24,extra='android:layout_marginTop="20dp"')+label('Sao lưu ảnh và video để có thể xem lại trên các thiết bị của bạn.',16,'@color/text_secondary','android:layout_marginTop="12dp" android:layout_marginBottom="24dp" android:lineSpacingExtra="4dp"')+'<com.google.android.material.switchmaterial.SwitchMaterial android:id="@+id/autoBackup" android:layout_width="match_parent" android:layout_height="72dp" android:text="Sao lưu khi mở ứng dụng" android:textColor="@color/text_primary" android:textSize="16sp"/><com.google.android.material.switchmaterial.SwitchMaterial android:id="@+id/wifiOnly" android:layout_width="match_parent" android:layout_height="72dp" android:text="Chỉ dùng Wi-Fi" android:textColor="@color/text_primary" android:textSize="16sp" android:checked="true"/>'+label('Các file đã sao lưu sẽ được bỏ qua ở lần tiếp theo.',14,'@color/text_secondary','android:layout_marginTop="20dp" android:layout_marginBottom="28dp"')+action('backupNow','Sao lưu ngay')+'<ProgressBar android:id="@+id/progress" style="?android:attr/progressBarStyleHorizontal" android:layout_width="match_parent" android:layout_height="12dp" android:layout_marginTop="20dp" android:max="100"/>'+status
    put('layout/activity_backup.xml',f'<LinearLayout {xmlns} android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="@color/background">{toolbar("Sao lưu và đồng bộ")}<androidx.core.widget.NestedScrollView android:layout_width="match_parent" android:layout_height="match_parent"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:padding="24dp">{backup}</LinearLayout></androidx.core.widget.NestedScrollView></LinearLayout>')

def polish_settings():
    xmlns=f'xmlns:android="{A}" xmlns:app="{P}"'
    put('drawable/ic_chevron_right.xml',f'<vector xmlns:android="{A}" android:width="20dp" android:height="20dp" android:viewportWidth="24" android:viewportHeight="24"><path android:fillColor="#526D99" android:pathData="M9,6l6,6l-6,6l-1.4,-1.4l4.6,-4.6l-4.6,-4.6Z"/></vector>')
    put('drawable/bg_settings_row.xml',f'<shape xmlns:android="{A}"><solid android:color="@color/surface"/><corners android:radius="12dp"/></shape>')
    def setting(id,title,icon,subtitle=''):
        color='#DB3546' if id=='logout' else '@color/text_primary'
        detail=label(subtitle,13,'@color/text_secondary',f'android:id="@+id/{id}Detail" android:layout_marginTop="3dp"') if subtitle else ''
        return f'''<LinearLayout android:id="@+id/{id}" android:layout_width="match_parent" android:layout_height="wrap_content" android:minHeight="56dp" android:layout_marginBottom="3dp" android:orientation="horizontal" android:gravity="center_vertical" android:paddingHorizontal="14dp" android:paddingVertical="12dp" android:background="@drawable/bg_settings_row" android:foreground="?attr/selectableItemBackground" android:clickable="true" android:focusable="true">
        <ImageView android:layout_width="22dp" android:layout_height="22dp" android:src="@drawable/{icon}" app:tint="{color}" android:importantForAccessibility="no"/>
        <LinearLayout android:layout_width="0dp" android:layout_weight="1" android:layout_height="wrap_content" android:orientation="vertical" android:layout_marginStart="16dp" android:layout_marginEnd="8dp">{label(title,15,color)}{detail}</LinearLayout>
        <ImageView android:layout_width="18dp" android:layout_height="18dp" android:src="@drawable/ic_chevron_right" app:tint="@color/text_hint" android:importantForAccessibility="no"/></LinearLayout>'''
    main=[('account','Tài khoản','ic_person','Đang tải tài khoản…'),('backup','Sao lưu và đồng bộ','ic_cloud_upload','Chưa bật'),('storage','Dung lượng lưu trữ','ic_album','Đang tính dung lượng…'),('notifications','Thông báo','ic_notification','Lịch sử hoạt động'),('theme','Giao diện','ic_settings','Sáng'),('language','Ngôn ngữ','ic_language','Tiếng Việt')]
    content=''.join(setting(*r) for r in main)
    content+=label('Thư viện',13,'@color/text_secondary','android:paddingTop="14dp" android:paddingBottom="8dp"')+setting('hiddenMedia','Ảnh và video đã ẩn','ic_visibility_off','Quản lý các mục đã ẩn')+setting('trash','Thùng rác','ic_delete','Khôi phục ảnh đã xóa')
    content+=label('Khác',13,'@color/text_secondary','android:paddingTop="14dp" android:paddingBottom="8dp"')+''.join(setting(*r) for r in [('about','Giới thiệu','ic_about'),('help','Trợ giúp','ic_help'),('logout','Đăng xuất','ic_logout')])
    content+=label('',14,'@color/text_secondary','android:id="@+id/status" android:visibility="gone" android:paddingVertical="12dp"')
    put('layout/activity_settings.xml',f'<LinearLayout {xmlns} android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="@color/background">{toolbar("Cài đặt")}<androidx.core.widget.NestedScrollView android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:fillViewport="true"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:paddingHorizontal="12dp" android:paddingBottom="16dp">{content}</LinearLayout></androidx.core.widget.NestedScrollView>{navigation()}</LinearLayout>')

def polish_secondary_screens():
    xmlns=f'xmlns:android="{A}" xmlns:app="{P}"'
    status=label('',14,'@color/text_secondary','android:id="@+id/status" android:visibility="gone" android:paddingVertical="8dp"')
    put('layout/activity_album.xml',f'<LinearLayout {xmlns} android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="@color/background"><FrameLayout android:layout_width="match_parent" android:layout_height="64dp">{toolbar("Album")}<com.google.android.material.button.MaterialButton android:id="@+id/createAlbum" style="@style/TextButton" android:layout_width="144dp" android:layout_height="40dp" android:layout_gravity="end|center_vertical" android:layout_marginEnd="16dp" android:backgroundTint="@color/primary_light" android:text="Tạo album" android:textSize="15sp" app:icon="@drawable/ic_add" app:iconGravity="textStart" app:cornerRadius="22dp"/></FrameLayout><LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:orientation="vertical" android:paddingHorizontal="12dp">{status}<androidx.recyclerview.widget.RecyclerView android:id="@+id/grid" android:layout_width="match_parent" android:layout_height="match_parent" android:clipToPadding="false" android:paddingBottom="16dp"/></LinearLayout>{navigation()}</LinearLayout>')
    put('layout/item_media_row.xml',f'''<LinearLayout {xmlns} android:layout_width="match_parent" android:layout_height="96dp" android:orientation="horizontal" android:gravity="center_vertical" android:paddingVertical="10dp"><com.google.android.material.card.MaterialCardView android:layout_width="76dp" android:layout_height="76dp" app:cardCornerRadius="10dp" app:strokeWidth="0dp"><ImageView android:id="@+id/thumbnail" android:layout_width="match_parent" android:layout_height="match_parent" android:scaleType="centerCrop" android:contentDescription="Ảnh trong thùng rác"/></com.google.android.material.card.MaterialCardView><TextView android:id="@+id/caption" android:layout_width="0dp" android:layout_weight="1" android:layout_height="wrap_content" android:layout_marginStart="16dp" android:textColor="@color/text_primary" android:textSize="15sp" android:maxLines="3" android:ellipsize="end" android:lineSpacingExtra="5dp"/><TextView android:id="@+id/check" android:layout_width="28dp" android:layout_height="28dp" android:visibility="gone" android:contentDescription="Đã chọn" android:background="@drawable/bg_selection_number" android:textColor="@color/white" android:textSize="14sp" android:fontFamily="sans-serif-medium" android:gravity="center" android:includeFontPadding="false" android:elevation="2dp"/></LinearLayout>''')
    put('layout/item_notification.xml',f'<LinearLayout {xmlns} android:layout_width="match_parent" android:layout_height="wrap_content" android:minHeight="88dp" android:orientation="horizontal" android:gravity="center_vertical" android:paddingVertical="16dp"><ImageView android:layout_width="40dp" android:layout_height="40dp" android:background="@drawable/bg_circle_icon" android:padding="10dp" android:src="@drawable/ic_notification" app:tint="@color/primary" android:contentDescription="Thông báo"/><TextView android:id="@+id/notificationMessage" android:layout_width="0dp" android:layout_weight="1" android:layout_height="wrap_content" android:layout_marginStart="16dp" android:textSize="15sp" android:textColor="@color/text_primary" android:lineSpacingExtra="5dp"/></LinearLayout>')
    # A photo-information card, with short labeled rows rather than one long block.
    rows=''
    for id,title,icon in [('infoDate','Thời gian nhập','ic_calendar'),('infoPath','Đường dẫn','ic_album'),('infoDevice','Thiết bị','ic_device'),('infoType','Loại file','ic_file_type')]:
        rows+=f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="horizontal" android:paddingVertical="16dp"><ImageView android:layout_width="24dp" android:layout_height="24dp" android:src="@drawable/{icon}" app:tint="@color/text_primary" android:contentDescription="{title}"/><LinearLayout android:layout_width="0dp" android:layout_weight="1" android:layout_height="wrap_content" android:layout_marginStart="16dp" android:orientation="vertical">'+label(title,15)+label('',14,'@color/text_secondary',f'android:id="@+id/{id}" android:layout_marginTop="4dp"')+'</LinearLayout></LinearLayout>'
    header='<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="horizontal" android:gravity="center_vertical" android:paddingVertical="16dp"><com.google.android.material.card.MaterialCardView android:layout_width="76dp" android:layout_height="76dp" app:cardCornerRadius="10dp" app:strokeWidth="0dp"><ImageView android:id="@+id/photo" android:layout_width="match_parent" android:layout_height="match_parent" android:scaleType="centerCrop" android:contentDescription="Ảnh xem trước"/></com.google.android.material.card.MaterialCardView><LinearLayout android:layout_width="0dp" android:layout_weight="1" android:layout_height="wrap_content" android:layout_marginStart="16dp" android:orientation="vertical">'+label('',16,extra='android:id="@+id/infoName"')+label('',14,'@color/text_secondary','android:id="@+id/infoSize" android:layout_marginTop="6dp"')+'</LinearLayout></LinearLayout>'
    put('layout/dialog_photo_info.xml',f'<LinearLayout {xmlns} android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="@color/background">{toolbar("Chi tiết")}<androidx.core.widget.NestedScrollView android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:paddingHorizontal="24dp" android:orientation="vertical">{header}{rows}</LinearLayout></androidx.core.widget.NestedScrollView><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:padding="24dp" android:orientation="vertical">{action("close","Đóng")}</LinearLayout></LinearLayout>')

if __name__=='__main__':polish()
